  if (t.length === 0 || t.length > s.length) return "";
  const need = {};
  for (let i = 0; i < t.length; i++) need[t[i]] = (need[t[i]] || 0) + 1;
  const keys = Object.keys(need);
  let bestLen = -1;
  let bestStart = -1;
  for (let l = 0; l < s.length; l++) {
    const have = {};
    for (let r = l; r < s.length; r++) {
      have[s[r]] = (have[s[r]] || 0) + 1;
      let ok = true;
      for (let k = 0; k < keys.length; k++) {
        const ch = keys[k];
        if ((have[ch] || 0) < need[ch]) { ok = false; break; }
      }
      if (ok) {
        const len = r - l + 1;
        if (bestLen === -1 || len < bestLen) { bestLen = len; bestStart = l; }
        break;
      }
    }
  }
  if (bestStart === -1) return "";
  return s.slice(bestStart, bestStart + bestLen);
}

function solve(s, t) {
  if (t.length === 0 || t.length > s.length) return "";
  const need = {};
  for (let i = 0; i < t.length; i++) need[t[i]] = (need[t[i]] || 0) + 1;
  const required = Object.keys(need).length;
  const have = {};
  let formed = 0;
  let bestLen = s.length + 1;
  let bestStart = -1;
  let l = 0;
  for (let r = 0; r < s.length; r++) {
    const ch = s[r];
    have[ch] = (have[ch] || 0) + 1;
    if (need[ch] !== undefined && have[ch] === need[ch]) formed++;
    while (formed === required) {
      if (r - l + 1 < bestLen) { bestLen = r - l + 1; bestStart = l; }
      const lc = s[l];
      have[lc]--;
      if (need[lc] !== undefined && have[lc] < need[lc]) formed--;
      l++;
    }
  }
  if (bestStart === -1) return "";
  return s.slice(bestStart, bestStart + bestLen);
}
